class Calculator:
    @staticmethod
    def add(x, y):
        return x + y

    @staticmethod
    def subtract(x, y):
        return x - y

    @staticmethod
    def multiply(x, y):
        return x * y

    @staticmethod
    def divide(x, y):
        if y != 0:
            return x / y
        else:
            return "Division by zero is not allowed."


print(Calculator.add(5, 3))        # 8
print(Calculator.subtract(10, 4))  # 6
print(Calculator.multiply(2, 6))   # 12
print(Calculator.divide(8, 2))     # 4.0
print(Calculator.divide(5, 0))     # Division by zero is not allowed.

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    @classmethod
    def from_birth_year(cls, name, birth_year):
        age = 2024 - birth_year
        return cls(name, age)

    def __str__(self):
        return f"{self.name} is {self.age} years old."


person1 = Person.from_birth_year("Alice", 1990)
person2 = Person.from_birth_year("Bob", 1985)

print(person1)  # Alice is 34 years old.
print(person2)  # Bob is 39 years old.
